'use strict';
const http = require('http');
const crypto = require('crypto');

// Binary message protocol parser for inter-service communication
// Format: [4-byte magic][2-byte version][2-byte header_len][header_len bytes header][payload]
// Header contains HMAC-SHA256 signature of payload

const MAGIC = Buffer.from([0x53, 0x56, 0x43, 0x31]); // 'SVC1'
const SHARED_SECRET = crypto.randomBytes(32);
const MAX_MESSAGE_SIZE = 65536;
const HEADER_OVERHEAD = 8; // magic(4) + version(2) + header_len(2)

const users = new Map([
  ['svc-auth', { id: 'svc-auth', secret: crypto.randomBytes(32), permissions: ['read', 'write'] }],
  ['svc-billing', { id: 'svc-billing', secret: crypto.randomBytes(32), permissions: ['read'] }],
]);

// Session store with sensitive tokens
const sessions = new Map();
function createSession(userId, metadata) {
  const token = crypto.randomBytes(48).toString('hex');
  const session = { userId, token, metadata, createdAt: Date.now(), refreshToken: crypto.randomBytes(64).toString('hex') };
  sessions.set(token, session);
  return session;
}

// Pre-populate some sessions
createSession('svc-auth', { internalKey: crypto.randomBytes(32).toString('hex'), endpoint: 'https://internal.corp/auth' });
createSession('svc-billing', { internalKey: crypto.randomBytes(32).toString('hex'), endpoint: 'https://internal.corp/billing' });

function computeHmac(data, secret) {
  return crypto.createHmac('sha256', secret).update(data).digest();
}

function safeCompare(a, b) {
  if (!Buffer.isBuffer(a)) a = Buffer.from(a);
  if (!Buffer.isBuffer(b)) b = Buffer.from(b);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

// Parse the binary protocol frame
function parseFrame(buffer) {
  if (!Buffer.isBuffer(buffer)) {
    return { error: 'Input must be a Buffer' };
  }

  if (buffer.length < HEADER_OVERHEAD) {
    return { error: 'Message too short' };
  }

  if (buffer.length > MAX_MESSAGE_SIZE) {
    return { error: 'Message exceeds maximum size' };
  }

  // Validate magic bytes
  const magic = buffer.slice(0, 4);
  if (!magic.equals(MAGIC)) {
    return { error: 'Invalid magic bytes' };
  }

  // Parse version (big-endian uint16)
  const version = buffer.readUInt16BE(4);
  if (version !== 1) {
    return { error: 'Unsupported protocol version' };
  }

  // Parse header length (big-endian uint16)
  const headerLen = buffer.readUInt16BE(6);

  // Bounds check: ensure header fits within the buffer
  // Header starts at offset HEADER_OVERHEAD and extends headerLen bytes
  const headerEnd = HEADER_OVERHEAD + headerLen;
  if (headerEnd >= buffer.length) {
    return { error: 'Header length exceeds buffer' };
  }

  // Extract header (contains HMAC signature + sender ID)
  const header = buffer.slice(HEADER_OVERHEAD, headerEnd);

  // Payload starts after header
  const payload = buffer.slice(headerEnd);

  return { version, headerLen, header, payload, headerEnd };
}

// Validate message authentication
function validateMessage(frame) {
  if (frame.error) return frame;

  // Header format: [32-byte HMAC][remaining = sender ID as UTF-8]
  if (frame.header.length < 33) {
    return { error: 'Header too short for signature' };
  }

  const signature = frame.header.slice(0, 32);
  const senderId = frame.header.slice(32).toString('utf-8').trim();

  const sender = users.get(senderId);
  if (!sender) {
    return { error: 'Unknown sender' };
  }

  // Verify HMAC of payload using sender's secret
  const expectedHmac = computeHmac(frame.payload, sender.secret);
  if (!safeCompare(signature, expectedHmac)) {
    return { error: 'Invalid signature' };
  }

  return { senderId, sender, payload: frame.payload };
}

// Process authenticated commands
function processCommand(validated) {
  if (validated.error) return validated;

  let command;
  try {
    command = JSON.parse(validated.payload.toString('utf-8'));
  } catch (e) {
    return { error: 'Invalid JSON payload' };
  }

  if (!command.action || typeof command.action !== 'string') {
    return { error: 'Missing action' };
  }

  // Check permissions
  if (command.action === 'list_sessions' && validated.sender.permissions.includes('read')) {
    const sessionList = [];
    sessions.forEach((sess, token) => {
      sessionList.push({ userId: sess.userId, createdAt: sess.createdAt, tokenPrefix: token.slice(0, 8) });
    });
    return { result: sessionList };
  }

  if (command.action === 'get_session' && validated.sender.permissions.includes('read')) {
    if (!command.tokenPrefix || typeof command.tokenPrefix !== 'string') {
      return { error: 'Missing tokenPrefix' };
    }
    let found = null;
    sessions.forEach((sess, token) => {
      if (token.startsWith(command.tokenPrefix)) {
        found = { userId: sess.userId, createdAt: sess.createdAt, metadata: sess.metadata };
      }
    });
    return found ? { result: found } : { error: 'Session not found' };
  }

  return { error: 'Unknown or unauthorized action' };
}

// HTTP interface for receiving binary protocol messages
const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/message') {
    const chunks = [];
    let totalSize = 0;

    req.on('data', (chunk) => {
      totalSize += chunk.length;
      if (totalSize > MAX_MESSAGE_SIZE) {
        res.writeHead(413);
        res.end(JSON.stringify({ error: 'Payload too large' }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      const buffer = Buffer.concat(chunks);
      const frame = parseFrame(buffer);
      const validated = validateMessage(frame);
      const result = processCommand(validated);

      res.writeHead(result.error ? 400 : 200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    });
  } else if (req.method === 'GET' && req.url === '/health') {
    res.writeHead(200);
    res.end(JSON.stringify({ status: 'ok' }));
  } else {
    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000);

module.exports = { parseFrame, validateMessage, processCommand, server, users, SHARED_SECRET };
